settings.custom_liquid:
{%- if request.locale.iso_code == 'fr' -%}
  {%- assign nur_rating_text = '4,6/5 avis de testeurs' -%}
  {%- assign nur_rating_label = 'Noté 4,6 sur 5 par nos testeurs' -%}
{%- else -%}
  {%- assign nur_rating_text = '4.6/5 tester reviews' -%}
  {%- assign nur_rating_label = 'Rated 4.6 out of 5 by our testers' -%}
{%- endif -%}
<a class="nur-rating" href="{% if routes.root_url == '/' %}/pages/reviews{% else %}{{ routes.root_url }}/pages/reviews{% endif %}" aria-label="{{ nur_rating_label }}">
  <span class="nur-rating__stars" aria-hidden="true"><span class="nur-rating__fill">★★★★★</span>★★★★★</span>
  <span class="nur-rating__text">{{ nur_rating_text }}</span>
</a>
<style>
  .nur-rating { display: inline-flex; align-items: center; gap: 8px; text-decoration: none; color: #1A1A1A; font-size: 13px; }
  .nur-rating__stars { position: relative; display: inline-block; color: #E5DCC7; letter-spacing: 2px; font-size: 15px; line-height: 1; }
  .nur-rating__fill { position: absolute; inset: 0 auto 0 0; width: 92%; overflow: hidden; white-space: nowrap; color: #C8A96E; }
  .nur-rating__text { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: rgba(26,26,26,0.25); }
  .nur-rating:hover .nur-rating__text { text-decoration-color: #1A1A1A; }
</style>
